from pathlib import Path
import base64

def write_text(path, content):
    p=Path(path); p.parent.mkdir(parents=True, exist_ok=True); p.write_text(content)

def write_b64(path, payload):
    p=Path(path); p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(base64.b64decode(payload))

